\section{Introduction}

\subsection{Arrow's theorem as an ultrafilter statement}
The modern proof of Arrow's impossibility theorem studies the family of
\emph{decisive coalitions} of a social welfare function satisfying unanimity and
independence of irrelevant alternatives. One shows that this family is closed
upward, closed under intersection, and satisfies the dichotomy that every
coalition or its complement belongs to it: it is an ultrafilter on the
electorate. On a finite set every ultrafilter is principal, generated by a single
point, and that point is the dictator. The Boolean structure of the ranking
domain is the engine of the impossibility.

This paper asks what remains when that Boolean structure is replaced by the
min-plus, or \emph{tropical}, semiring $(\R\cup\{+\infty\},\min,+)$. Profiles
become vectors of real scores and the aggregation axioms become tropical
linearity conditions. The entire architecture survives, in a sharper and more
quantitative form: instead of an all-or-nothing impossibility one obtains a
complete classification, with dictatorship a single distinguished point in a
polyhedral continuum, and a suite of exact numerical invariants measuring the
distance from it.

\subsection{Tropical algebra}
On $\R\cup\{+\infty\}$ define $a\oplus b=\min(a,b)$ and $a\odot b=a+b$. Then
$\oplus$ is associative, commutative and idempotent with neutral element
$+\infty$; $\odot$ is associative and commutative with neutral element $0$; and
$\odot$ distributes over $\oplus$. There are no additive inverses. A
\emph{tropical linear form} is
$\bigoplus_{i\in S}\delta_i\odot x_i=\min_{i\in S}(x_i+\delta_i)$; tropical
polynomials are exactly the concave piecewise-linear functions with integral
slopes. Tropical arithmetic arises as the $\varepsilon\downarrow 0$ limit of
ordinary arithmetic conjugated by $a\mapsto e^{-a/\varepsilon}$, a procedure
known as \emph{Maslov dequantization}; Section~\ref{sec:dequant} makes this
precise here.

\section{Setting and axioms}

Throughout, $\voters$ is a finite nonempty set of \emph{voters}, $n=|\voters|$; a
\emph{profile} is a vector $x\in\R^{\voters}$ of real scores (lower means more
critical); an \emph{aggregator} is a function $F:\R^{\voters}\to\R$. We write
$(x\wedge y)_i=\min(x_i,y_i)$ and $c\one$ for the constant profile.

\begin{definition}[Tropical aggregator]
An aggregator $F$ is a \emph{tropical aggregator} if
\begin{enumerate}
\item[(T1)] \textbf{tropical additivity:} $F(x\wedge y)=\min\bigl(F(x),F(y)\bigr)$
  for all $x,y$;
\item[(T2)] \textbf{translation equivariance:} $F(x+c\one)=F(x)+c$ for all $x$ and
  all $c\in\R$;
\item[(T3)] \textbf{normalization:} $F(\vzero)=0$.
\end{enumerate}
\end{definition}

Axiom (T1) says $F$ is a homomorphism for tropical addition; (T2) is equivariance
for tropical scalar multiplication and is exactly the condition making $F$
well-defined on the tropical projective space $\R^{\voters}/\R\one$; (T3) is a
harmless normalization.

\begin{lemma}[Constants]\label{lem:const}
$F(c\one)=c$ for all $c\in\R$.
\end{lemma}
\begin{proof}
Apply (T2) with $x=\vzero$ and use (T3).
\end{proof}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $x_i\le y_i$ for all $i$ then $F(x)\le F(y)$.
\end{lemma}
\begin{proof}
Then $x\wedge y=x$, so $F(x)=\min(F(x),F(y))\le F(y)$ by (T1).
\end{proof}

Monotonicity is thus a consequence, not an axiom.

\begin{lemma}[Finite tropical additivity]\label{lem:inf}
For any nonempty finite family of profiles $y^{(1)},\dots,y^{(m)}$,
$F\bigl(\bigwedge_{a} y^{(a)}\bigr)=\min_{a} F\bigl(y^{(a)}\bigr)$.
\end{lemma}
\begin{proof}
Induction on $m$ using (T1).
\end{proof}

\section{Classification of finite min-plus aggregators}

\subsection{The dip calculus}

\begin{definition}[Dip profile]
For a voter $i$ and $t\in\R$ let $d_i(t)$ be the profile with $d_i(t)_i=t$ and
$d_i(t)_j=0$ for $j\ne i$. Write $\varphi_i(t)=F(d_i(t))$.
\end{definition}

\begin{lemma}[Range of a dip]\label{lem:diprange}
For $t\le 0$, $t\le\varphi_i(t)\le 0$.
\end{lemma}
\begin{proof}
$t\one\le d_i(t)\le\vzero$ coordinatewise; apply Lemmas~\ref{lem:const}
and~\ref{lem:mono}.
\end{proof}

\begin{lemma}[Dip functional equation]\label{lem:dipkey}
For $t\le s\le 0$,
\[
\min\bigl(\varphi_i(t),\,s\bigr)=s+\varphi_i(t-s).
\]
\end{lemma}
\begin{proof}
Coordinatewise $d_i(t)\wedge s\one$ has entry $t$ at $i$ (as $t\le s$) and $s$
elsewhere (as $s\le 0$), i.e. $d_i(t)\wedge s\one=d_i(t-s)+s\one$. Apply (T1) on
the left, (T2) and Lemma~\ref{lem:const} on the right.
\end{proof}

\begin{definition}[Active voter]
Voter $i$ is \emph{active} for $F$ if $\varphi_i(t)<0$ for some $t\le 0$.
\end{definition}

\begin{proposition}[Shape of a dip]\label{prop:dipshape}
Let $F$ be a tropical aggregator and $i$ a voter.
\begin{enumerate}
\item If $i$ is not active then $\varphi_i(u)=0$ for all $u\le 0$.
\item If $i$ is active, witnessed by $t_0\le 0$ with $\varphi_i(t_0)<0$, then
$\delta_i:=\varphi_i(t_0)-t_0$ satisfies $\delta_i\ge 0$ and
\[
\varphi_i(u)=\min(u+\delta_i,\ 0)\qquad\text{for all }u\le 0 .
\]
In particular $\delta_i$ is independent of the witness $t_0$.
\end{enumerate}
\end{proposition}
\begin{proof}
(1) is immediate from Lemma~\ref{lem:diprange}. For (2), $\delta_i\ge0$ since
$t_0\le\varphi_i(t_0)$.

Suppose first $t_0\le u\le 0$. Apply Lemma~\ref{lem:dipkey} with $t=t_0$ and
$s=t_0-u\in[t_0,0]$, noting $t_0-(t_0-u)=u$:
\[
\min\bigl(\varphi_i(t_0),\,t_0-u\bigr)=(t_0-u)+\varphi_i(u).
\]
If $\varphi_i(t_0)\le t_0-u$ this gives $\varphi_i(u)=u+\delta_i\le 0$;
otherwise it gives $\varphi_i(u)=0$ and $u+\delta_i\ge 0$. Either way
$\varphi_i(u)=\min(u+\delta_i,0)$.

Now suppose $u\le t_0$. Monotonicity gives $\varphi_i(u)\le\varphi_i(t_0)<0$.
Applying the previous paragraph with $u$ as witness and evaluating at $t_0$ gives
$\varphi_i(t_0)=\min(t_0+(\varphi_i(u)-u),0)$; since $\varphi_i(t_0)<0$ the first
branch is attained, so $\varphi_i(t_0)=t_0+\varphi_i(u)-u$, i.e.
$\varphi_i(u)=u+\delta_i$. This value is negative, hence equals
$\min(u+\delta_i,0)$.
\end{proof}

Proposition~\ref{prop:dipshape} is the crux: the axioms rigidify the
one-parameter probe $\varphi_i$ into a \emph{clamped translate}, encoded by the
single nonnegative number $\delta_i$, the depth to which voter $i$ must dip
before being heard.

\subsection{The representation theorem}

\begin{theorem}[Classification of finite min-plus aggregators]\label{thm:repr}
Let $\voters$ be finite and nonempty and $F$ a tropical aggregator. There exist a
nonempty $S\subseteq\voters$ and weights $\delta$ with $\delta_i\ge0$ for
$i\in S$, $\min_{i\in S}\delta_i=0$, and $S$ equal to the set of active voters,
such that
\[
F(x)=\min_{i\in S}\ (x_i+\delta_i)\qquad\text{for all }x\in\R^{\voters}.
\]
\end{theorem}
\begin{proof}
Let $S$ be the set of active voters, and for $i\in S$ let $\delta_i\ge0$ be the
weight of Proposition~\ref{prop:dipshape}(2).

\emph{$S$ is nonempty.} If every voter were inactive, note that
$\bigwedge_{i\in\voters}d_i(-1)=-\one$ coordinatewise (at coordinate $j$ the term
$i=j$ contributes $-1$). By Lemma~\ref{lem:inf} the left side has $F$-value
$\min_i\varphi_i(-1)=0$, whereas $F(-\one)=-1$ by Lemma~\ref{lem:const}; a
contradiction.

\emph{The formula.} Fix $x$, set $A=\min_{i\in S}(x_i+\delta_i)$ and
$K=\max\{\max_j x_j,\ A\}$. Define $y^{(i)}$ by $y^{(i)}_i=x_i$ and
$y^{(i)}_j=K$ for $j\ne i$. Then $\bigwedge_i y^{(i)}=x$, and
$y^{(i)}=d_i(x_i-K)+K\one$ with $x_i-K\le 0$, so by (T2) and
Proposition~\ref{prop:dipshape}
\[
F\bigl(y^{(i)}\bigr)=K+\varphi_i(x_i-K)=
\begin{cases}\min(x_i+\delta_i,\ K), & i\in S,\\ K, & i\notin S.\end{cases}
\]
Lemma~\ref{lem:inf} gives $F(x)=\min_i F(y^{(i)})$. Every term is $\ge\min(A,K)=A$,
and the term at a minimizer $i_0\in S$ of $x_i+\delta_i$ equals $A$. Hence
$F(x)=A$.

\emph{Normalization.} Evaluating at $x=\vzero$ with (T3) gives
$\min_{i\in S}\delta_i=0$.
\end{proof}

\begin{theorem}[Uniqueness of support and weights]\label{thm:unique}
Suppose $F(x)=\min_{i\in S}(x_i+\delta_i)=\min_{i\in T}(x_i+\gamma_i)$ for all
$x$, with $S,T$ nonempty, $\delta\ge0$ on $S$, $\min_S\delta=0$, $\gamma\ge0$ on
$T$, $\min_T\gamma=0$. Then $S=T$ and $\delta_i=\gamma_i$ for all $i\in S$.
\end{theorem}
\begin{proof}
The key computation is that any such representation predicts, for $t\le 0$,
\[
F\bigl(d_i(t)\bigr)=
\begin{cases}\min(t+\delta_i,\ 0), & i\in S,\\ 0,& i\notin S,\end{cases}
\]
since the term at $i$ (if present) is $t+\delta_i$ while the other terms are the
$\delta_j\ge0$, whose minimum is $0$ by normalization. Fix $i\in S$ and take
$t\le -(\delta_i+|\gamma_i|+1)$, so that $t+\delta_i<0$ and $t+\gamma_i<0$. Then
$F(d_i(t))=t+\delta_i<0$, forcing $i\in T$ and $t+\gamma_i=t+\delta_i$, i.e.
$\gamma_i=\delta_i$. Symmetry finishes.
\end{proof}

Hence $S$ is an intrinsic invariant of $F$: the \emph{irredundant tropical
support}.

\subsection{The literal projection conjecture is false}

\begin{definition}
$F$ is a \emph{minimum of coordinate projections} if $F(x)=\min_{i\in S}x_i$ for
some nonempty $S$.
\end{definition}

\begin{theorem}[Counterexample]\label{thm:counter}
On the two-voter electorate $\{0,1\}$ set $W(x_0,x_1)=\min(x_0,\ x_1+1)$. Then
$W$ is a tropical aggregator but is not a minimum of coordinate projections.
\end{theorem}
\begin{proof}
(T1) is checked by splitting into the four orderings of $x_0$ against $y_0$ and
$x_1$ against $y_1$; each case is a linear inequality. (T2) holds since both
branches shift by $c$. (T3): $W(0,0)=\min(0,1)=0$. Finally at $x=(1,-1)$ we get
$W(x)=\min(1,0)=0$, while a minimum of coordinate projections always returns one
of the coordinates of $x$, here $1$ or $-1$.
\end{proof}

Tropical weights are therefore genuinely permitted; Theorem~\ref{thm:repr} is
sharp, and the naive projection statement is a strict overreach. The obstruction
is exactly that a weighted tropical form can output a value nobody submitted.

\begin{definition}[Selectivity]
$F$ is \emph{selective} if for every $x$ there is $i$ with $F(x)=x_i$.
\end{definition}

\begin{theorem}[Corrected classification]\label{thm:selective}
Let $F(x)=\min_{i\in S}(x_i+\delta_i)$ be a normalized tropical representation.
If $F$ is selective then $\delta\equiv 0$ on $S$, hence $F(x)=\min_{i\in S}x_i$.
\end{theorem}
\begin{proof}
Suppose $\delta_i>0$ for some $i\in S$, and take $t=-(\delta_i+1)$. The dip
computation in the proof of Theorem~\ref{thm:unique} gives
$F(d_i(t))=t+\delta_i=-1$. But the coordinates of $d_i(t)$ are only
$t=-(\delta_i+1)\ne -1$ and $0\ne-1$, contradicting selectivity.
\end{proof}

\begin{theorem}[Anonymity forces unanimity]\label{thm:anon}
If a normalized tropical aggregator $F(x)=\min_{i\in S}(x_i+\delta_i)$ satisfies
$F(x\circ\sigma)=F(x)$ for every permutation $\sigma$ of $\voters$ and every $x$,
then $S=\voters$ and $\delta\equiv 0$, i.e. $F(x)=\min_{i}x_i$. In particular an
anonymous tropical aggregator is never a dictatorship when $n\ge2$.
\end{theorem}
\begin{proof}
Composing a dip with the transposition of $a$ and $i$ turns $d_a(t)$ into
$d_i(t)$, so anonymity gives $F(d_a(t))=F(d_i(t))$ for all $t\le0$. By the dip
computation this forces $a\in S\iff i\in S$ and $\delta_a=\delta_i$. Since $S$ is
nonempty, $S=\voters$ and $\delta$ is constant; normalization makes the constant
$0$.
\end{proof}

\section{Dependence sets, filters, and the Arrow threshold}

\begin{definition}[Dependence set]
A coalition $C\subseteq\voters$ is a \emph{dependence set} (\emph{decisive
coalition}) for $F$ if $F(x)=F(y)$ whenever $x_i=y_i$ for all $i\in C$. Let
$\Dep(F)$ denote the family of dependence sets.
\end{definition}

\begin{theorem}[Dependence is a principal filter]\label{thm:dep}
For a normalized tropical representation $F(x)=\min_{i\in S}(x_i+\delta_i)$,
\[
\Dep(F)=\{\,C\subseteq\voters:\ S\subseteq C\,\}.
\]
\end{theorem}
\begin{proof}
($\supseteq$) If $S\subseteq C$ and $x,y$ agree on $C$ they agree on $S$, and the
formula reads only coordinates in $S$.

($\subseteq$) Let $C\in\Dep(F)$ and suppose $i\in S\setminus C$. Put
$t=-(\delta_i+1)$. The profiles $\vzero$ and $d_i(t)$ agree on $C$, so
$F(\vzero)=F(d_i(t))$; but $F(\vzero)=0$ and $F(d_i(t))=\min(t+\delta_i,0)=-1$.
\end{proof}

Thus $\Dep(F)$ has all the ultrafilter properties (upward closure, closure under
intersection, properness) except the dichotomy. The dichotomy is exactly what
pins down a dictator.

\begin{theorem}[Tropical Arrow theorem]\label{thm:arrow}
For a normalized tropical representation $F(x)=\min_{i\in S}(x_i+\delta_i)$ the
following are equivalent:
\begin{enumerate}
\item \emph{(Ultrafilter dichotomy)} for every $C\subseteq\voters$, either
$C\in\Dep(F)$ or $C^{\complement}\in\Dep(F)$;
\item \emph{(Dictatorship)} there is a voter $i_0$ with $F(x)=x_{i_0}$ for all
$x$;
\item \emph{(Singleton support)} $|S|=1$.
\end{enumerate}
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:dep}, $C\in\Dep(F)\iff S\subseteq C$.

$(1)\Rightarrow(3)$: fix $a\in S$ and suppose $b\in S$, $b\ne a$. Test the
dichotomy on $C=\{b\}^{\complement}$. $C$ is not decisive since $b\in S\not\subseteq C$;
so $\{b\}$ is decisive, i.e. $S\subseteq\{b\}$, contradicting $a\in S$.

$(3)\Rightarrow(2)$: if $S=\{a\}$ then normalization gives $\delta_a=0$, so
$F(x)=x_a$.

$(2)\Rightarrow(1)$: by Theorem~\ref{thm:unique} a dictatorship has
$S=\{i_0\}$, so $\Dep(F)=\{C: i_0\in C\}$, and exactly one of $C$,
$C^{\complement}$ contains $i_0$.
\end{proof}

\begin{remark}
Theorem~\ref{thm:arrow} exhibits the Arrow phenomenon as a statement about the
\emph{cardinality of the support of a tropical linear form}. The rule $W$ of
Theorem~\ref{thm:counter} has support of size $2$ and is a legitimate
non-dictatorial tropical rule; unanimity $\min_i x_i$ has full support. The
tropical axioms admit an entire lattice of rules indexed by (support, weights),
with dictatorship a single distinguished point.
\end{remark}

\section{The exact anonymity defect}

\begin{definition}
For a coalition $S$ let $\Orb(S)=\{T\subseteq\voters:|T|=|S|\}$.
\end{definition}

\begin{proposition}\label{prop:orbit}
$T\in\Orb(S)$ if and only if $\sigma(S)=T$ for some permutation $\sigma$ of
$\voters$; and $|\Orb(S)|=\binom{n}{k}$ with $k=|S|$.
\end{proposition}
\begin{proof}
Permutations preserve cardinality. Conversely a bijection $S\to T$ exists when
$|S|=|T|$, and extends to a permutation of $\voters$ since the complements also
have equal cardinality; its image of $S$ is contained in $T$ and of the same
size, hence equals $T$. The count is the number of $k$-subsets of an $n$-set.
\end{proof}

\begin{proposition}\label{prop:uniquedec}
$\{T\in\Orb(S): S\subseteq T\}=\{S\}$.
\end{proposition}
\begin{proof}
$|T|=|S|$ and $S\subseteq T$ force $T=S$.
\end{proof}

\begin{theorem}[Exact anonymity--independence tradeoff]\label{thm:defect}
Let $F(x)=\min_{i\in S}(x_i+\delta_i)$ be a normalized tropical aggregator on $n$
voters with irredundant support of size $k$. Among the $\binom{n}{k}$ coalitions
in the permutation orbit of the minimal decisive coalition $S$, exactly one ---
$S$ itself --- is a dependence set. Hence
\[
\frac{\#\{T\in\Orb(S):T\notin\Dep(F)\}}{|\Orb(S)|}=1-\frac{1}{\binom{n}{k}} .
\]
Being an identity, the bound is sharp.
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:dep} with Propositions~\ref{prop:orbit}
and~\ref{prop:uniquedec}, and divide, noting $\binom{n}{k}\ge1$.
\end{proof}

The invariant $1-1/\binom{n}{k}$ is a \emph{defect of anonymity}. A dictatorship
($k=1$) has defect $1-1/n$; unanimity ($k=n$) has defect $0$; the defect is
maximal, on a large electorate, near $k\approx n/2$.

\section{Polyhedral geometry: chambers, cells, and the exchange law}

Fix a nonempty support $S$ and weights $\delta$; write
$F(x)=\min_{i\in S}(x_i+\delta_i)$ and $m_i(x)=x_i+\delta_i$ for the
\emph{tropical monomials}.

\subsection{Chambers}

\begin{definition}[Chamber]
$\Ch_i=\{x\in\R^{\voters}: m_i(x)\le m_j(x)\ \forall j\in S\}$.
\end{definition}

\begin{theorem}\label{thm:chambers}
\begin{enumerate}
\item Each $\Ch_i$ is a convex polyhedron.
\item If $F(x)=m_i(x)$ then $x\in\Ch_i$.
\item $\bigcup_{i\in S}\Ch_i=\R^{\voters}$.
\item If $i\in S$ and $x\in\Ch_i$ then $F(x)=m_i(x)$.
\item If $i,j\in S$ and $x\in\Ch_i\cap\Ch_j$ then $m_i(x)=m_j(x)$.
\item $F$ is concave on $\R^{\voters}$.
\end{enumerate}
\end{theorem}
\begin{proof}
(1) $\Ch_i$ is an intersection of closed affine half-spaces $\{m_i\le m_j\}$;
convexity follows since for $a,b\ge0$ with $a+b=1$ one has
$a\delta_i+b\delta_i=\delta_i$, so the inequalities are preserved. (2) and (4)
follow from $F\le m_i$ and $F=\min_j m_j$. (3) holds since the minimum over the
finite nonempty $S$ is attained. (5) is antisymmetry. (6) For $a,b\ge0$,
$a+b=1$, and each $j\in S$, $aF(x)+bF(y)\le a\,m_j(x)+b\,m_j(y)=m_j(ax+by)$;
minimize over $j$.
\end{proof}

\subsection{The complex of decisive coalitions}

\begin{definition}[Decisive coalition at a profile]
$D(x)=\{i\in S: m_i(x)=F(x)\}$.
\end{definition}

\begin{theorem}
$D(x)$ is always nonempty, and $i\in D(x)$ iff $i\in S$ and $x\in\Ch_i$.
\end{theorem}
\begin{proof}
The minimum over the finite nonempty $S$ is attained; the second claim is
Theorem~\ref{thm:chambers}(2),(4).
\end{proof}

\begin{definition}[Closed cell]
For $T\subseteq\voters$, $\Fc_T=\{x: T\subseteq D(x)\}$.
\end{definition}

\begin{theorem}[Cells are polyhedra]\label{thm:cells}
For $T\subseteq S$, $\Fc_T=\bigcap_{i\in T}\Ch_i$ is convex, and $m_i(x)=m_j(x)$
for all $i,j\in T$ and $x\in\Fc_T$.
\end{theorem}
\begin{proof}
Immediate from the previous theorem and Theorem~\ref{thm:chambers}(1); both
monomials equal $F(x)$.
\end{proof}

\begin{theorem}[The label is genuinely decisive]\label{thm:localdec}
If $y_i=x_i$ for all $i\in D(x)$ and $y_i\ge x_i$ for all $i$, then $F(y)=F(x)$.
\end{theorem}
\begin{proof}
Pick $i\in D(x)$: $F(y)\le m_i(y)=m_i(x)=F(x)$. Conversely $m_j(y)\ge m_j(x)\ge F(x)$
for every $j\in S$, so $F(y)\ge F(x)$.
\end{proof}

\begin{theorem}[Completeness of the labelling]\label{thm:complete}
For every nonempty $T\subseteq S$ there is a profile $x$ with $D(x)=T$. Hence the
cells are labelled exactly by the nonempty subcoalitions of $S$.
\end{theorem}
\begin{proof}
Set $x_i=-\delta_i$ for $i\in T$ and $x_i=1-\delta_i$ otherwise; then $m_i(x)=0$
on $T$ and $=1$ off $T$, so $F(x)=0$ with the minimum attained exactly on $T$.
\end{proof}

\subsection{The face lattice}

\begin{theorem}[Order anti-isomorphism]\label{thm:facelattice}
For nonempty $T\subseteq S$ and arbitrary $T'$,
$\Fc_T\subseteq\Fc_{T'}\iff T'\subseteq T$. Consequently $T\mapsto\Fc_T$ is
injective and inclusion-reversing, strictly larger labels give strictly smaller
faces, and $\Fc_{T\cup T'}=\Fc_T\cap\Fc_{T'}$.
\end{theorem}
\begin{proof}
($\Leftarrow$) is Theorem~\ref{thm:cells}. ($\Rightarrow$) take $x$ with
$D(x)=T$ from Theorem~\ref{thm:complete}; then $x\in\Fc_T\subseteq\Fc_{T'}$, so
$T'\subseteq D(x)=T$. The union formula restates
$T\cup T'\subseteq D(x)\iff T\subseteq D(x)$ and $T'\subseteq D(x)$.
\end{proof}

\subsection{Walls, flats and the support matroid}

\begin{definition}[Wall]
$H_{ij}=\{x: m_i(x)=m_j(x)\}$.
\end{definition}

\begin{theorem}[Walls containing a cell are the edges inside its label]\label{thm:walls}
For nonempty $T\subseteq S$ and any $i,j$,
\[
\Fc_T\subseteq H_{ij}\iff (i\in T\text{ and }j\in T)\text{ or }i=j .
\]
\end{theorem}
\begin{proof}
If $i,j\in T$ this is Theorem~\ref{thm:cells}; $i=j$ is trivial. Conversely
suppose $i\ne j$ and, without loss of generality, $i\notin T$. Refine the profile
of Theorem~\ref{thm:complete}: put $x_k=-\delta_k$ for $k\in T$ and
$x_k=c_k-\delta_k$ for $k\notin T$ with the $c_k$ pairwise distinct and strictly
positive. Then $D(x)=T$, so $x\in\Fc_T$, while $m_i(x)=c_i$ differs from $m_j(x)$
(which is $0$ if $j\in T$, else $c_j\ne c_i$). Hence $\Fc_T\not\subseteq H_{ij}$.
\end{proof}

Encoding $H_{ij}$ as the edge $\{i,j\}$ of the complete graph $K_S$,
Theorem~\ref{thm:walls} says the walls containing $\Fc_T$ form the edge set of
$K_T$, which is the flat of the graphic matroid of $K_S$ spanned by $K_T$; its
rank is $|T|-1$. We call this matroid the \emph{support matroid} of $F$.

\begin{theorem}[A star is a basis of the flat]\label{thm:star}
For nonempty $T\subseteq S$ and any $i_0\in T$,
\[
\Fc_T=\Fc_{\{i_0\}}\cap\bigcap_{i\in T}H_{i i_0}.
\]
Thus the $|T|-1$ equations $m_i=m_{i_0}$, $i\in T\setminus\{i_0\}$, cut the cell
out of the chamber of $i_0$: the star of $i_0$ in $K_T$ spans the flat and has
exactly the cardinality of its rank, hence is a basis.
\end{theorem}
\begin{proof}
($\subseteq$) is Theorem~\ref{thm:cells}. ($\supseteq$) if $x\in\Ch_{i_0}$ then
$F(x)=m_{i_0}(x)$, and the wall equations give $m_i(x)=F(x)$ for all $i\in T$.
\end{proof}

\subsection{Codimension}

\begin{definition}[Direction space]
$V_T=\{v\in\R^{\voters}: v_i=v_j\ \forall i,j\in T\}$, the profiles constant on
$T$.
\end{definition}

\begin{theorem}[Dimension count]\label{thm:dim}
For nonempty $T\subseteq\voters$, $\dim V_T+|T|=n+1$.
\end{theorem}
\begin{proof}
Fix $i_0\in T$ and let $L:\R^{\voters}\to\R^{T\setminus\{i_0\}}$,
$L(v)_i=v_i-v_{i_0}$. Then $\ker L=V_T$ and $L$ is surjective, so rank--nullity
gives $\dim V_T+(|T|-1)=n$.
\end{proof}

\begin{theorem}[Codimension of a cell]\label{thm:codim}
If $x,y\in\Fc_T$ then $y-x\in V_T$; and for nonempty $T\subseteq S$ there is a
profile in $\Fc_T$ at which every monomial indexed outside $T$ is strictly
larger, so $\Fc_T$ is relatively open in its affine span. Hence $\Fc_T$ has
codimension exactly $|T|-1$, the rank of the corresponding flat.
\end{theorem}
\begin{proof}
For $i,j\in T$ both $x$ and $y$ satisfy $x_i+\delta_i=x_j+\delta_j$, so
$(y-x)_i=(y-x)_j$. The strict profile is that of Theorem~\ref{thm:complete}.
Combine with Theorem~\ref{thm:dim}.
\end{proof}

Thus \emph{the codimension of a cell equals one less than the number of voters
simultaneously decisive on it}: chambers are top-dimensional, walls have
codimension $1$, and the deepest cell $T=S$ has codimension $|S|-1$.

\subsection{The single-voter exchange law}

\begin{theorem}[Exchange onto a wall]\label{thm:wallexch}
Let $i\ne j$ lie in $S$ and $x\in\Ch_i$. Define $y$ by changing only voter $j$:
$y_j=x_i+\delta_i-\delta_j$ and $y_k=x_k$ for $k\ne j$. Then
$\{i,j\}\subseteq D(y)$.
\end{theorem}
\begin{proof}
$m_i(y)=m_i(x)$ and $m_j(y)=x_i+\delta_i=m_i(x)$; for $k\ne j$,
$m_k(y)=m_k(x)\ge m_i(x)$ since $x\in\Ch_i$. Hence $F(y)=m_i(x)$ and both $i,j$
attain it.
\end{proof}

\begin{theorem}[Single-voter exchange]\label{thm:exch}
With the same hypotheses, for every $\varepsilon>0$ the profile $z$ with
$z_j=x_i+\delta_i-\delta_j-\varepsilon$ and $z_k=x_k$ for $k\ne j$ satisfies
$D(z)=\{j\}$.
\end{theorem}
\begin{proof}
$m_j(z)=m_i(x)-\varepsilon$, while $m_k(z)=m_k(x)\ge m_i(x)>m_j(z)$ for every
$k\in S\setminus\{j\}$.
\end{proof}

\begin{corollary}[Adjacency of top-dimensional cells]
Any two chambers $\Ch_i,\Ch_j$ with $i\ne j$ in $S$ share the codimension-one
face labelled $\{i,j\}$ (nonempty by Theorem~\ref{thm:complete}), and the
passage from the open cell $\{i\}$ to the open cell $\{j\}$ is realized by
changing the score of the single voter $j$.
\end{corollary}

This is a genuine exchange law, mirroring basis exchange in the support matroid.
Socially: a single voter can seize decisiveness unilaterally, without coalition
building.

\section{Maslov dequantization: the classical limit}\label{sec:dequant}

\begin{definition}[Log-sum-exp]
For $\varepsilon>0$, nonempty finite $S$ and $a:\voters\to\R$, set
$L_\varepsilon(a)=-\varepsilon\log\bigl(\sum_{i\in S}e^{-a_i/\varepsilon}\bigr)$,
and define the \emph{dequantized aggregator}
\[
F_\varepsilon(x)=L_\varepsilon(x_\bullet+\delta_\bullet)
 = -\varepsilon\log\sum_{i\in S}\exp\!\Bigl(-\frac{x_i+\delta_i}{\varepsilon}\Bigr).
\]
\end{definition}

$F_\varepsilon$ is real-analytic, strictly increasing in each variable and
translation-equivariant; it is the free energy of a Gibbs measure at temperature
$\varepsilon$ with energy levels $x_i+\delta_i$, and the softmin used to smooth
$\min$-pooling. It is not tropically additive: it is a genuinely classical
object.

\begin{theorem}[Explicit dequantization sandwich]\label{thm:sandwich}
Let $A=\min_{i\in S}a_i$. For every $\varepsilon>0$,
\[
A-\varepsilon\log|S|\ \le\ L_\varepsilon(a)\ \le\ A .
\]
\end{theorem}
\begin{proof}
With $\Sigma=\sum_{i\in S}e^{-a_i/\varepsilon}$, positivity of the terms and
$a_i\ge A$ give $e^{-A/\varepsilon}\le\Sigma\le|S|e^{-A/\varepsilon}$. Taking
logarithms, $-A/\varepsilon\le\log\Sigma\le\log|S|-A/\varepsilon$; multiplying by
$-\varepsilon<0$ reverses the inequalities.
\end{proof}

\begin{corollary}[Uniform convergence with explicit rate]\label{cor:unif}
For all $\varepsilon>0$ and all $x$,
$\bigl|F_\varepsilon(x)-F(x)\bigr|\le\varepsilon\log|S|$; hence
$F_\varepsilon\to F$ as $\varepsilon\downarrow0$, uniformly in the profile.
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:sandwich} with $a_i=x_i+\delta_i$ and note
$\log|S|\ge0$; the bound is independent of $x$, and squeezing gives the limit.
\end{proof}

\begin{theorem}[Dequantization stability equals dictatorship]\label{thm:exact}
$\bigl(\forall\varepsilon>0,\ \forall x,\ F_\varepsilon(x)=F(x)\bigr)\iff|S|=1$.
\end{theorem}
\begin{proof}
($\Leftarrow$) With $S=\{i_0\}$ the sum has one term and
$-\varepsilon\log e^{-(x_{i_0}+\delta_{i_0})/\varepsilon}=x_{i_0}+\delta_{i_0}=F(x)$.

($\Rightarrow$) Test at $\varepsilon=1$ and $x_i=-\delta_i$: then $m_i(x)=0$ for
all $i$, so $F(x)=0$ while $F_1(x)=-\log|S|$. Equality forces $|S|=1$.
\end{proof}

\begin{remark}
The quantity $\varepsilon\log|S|$ is temperature times the Boltzmann entropy of
the uniform distribution on the support. Thus a social rule is
temperature-independent exactly when its decisive coalition is a single voter:
dictatorship is the zero-entropy state.
\end{remark}

\section{Algorithms}

\subsection{Support-and-weight identification from a dip oracle}
Given oracle access to a tropical aggregator, Proposition~\ref{prop:dipshape} and
Theorem~\ref{thm:unique} give an identification algorithm using $O(n)$ queries.
For each voter $i$ query $F(d_i(-M))$ for a sufficiently deep $M>0$: if the value
is $0$ then $i\notin S$; if it is $v<0$ then $i\in S$ and $\delta_i=v+M$
(valid as soon as $M>\delta_i$, which is certified by doubling $M$ until the
value is strictly negative). Finally check $\min_{i\in S}\delta_i=0$.

\subsection{Decisive-coalition labelling}
Given $S$, $\delta$ and $x$, compute $m_i(x)$ for $i\in S$ in $O(|S|)$, take
$F(x)=\min_i m_i(x)$ and return $D(x)=\{i: m_i(x)=F(x)\}$. By
Theorem~\ref{thm:codim} the containing cell has codimension $|D(x)|-1$, and by
Theorem~\ref{thm:star} it is cut out of the chamber of any $i_0\in D(x)$ by
$|D(x)|-1$ wall equations.

\subsection{Exchange-path construction}
Given $x\in\Ch_i$ and a target $j\ne i$, Theorems~\ref{thm:wallexch}
and~\ref{thm:exch} produce in $O(1)$ operations the wall point
($x_j:=m_i(x)-\delta_j$) and, for any $\varepsilon>0$, a point of the open cell
$\{j\}$ ($x_j:=m_i(x)-\delta_j-\varepsilon$). Iterating walks a path through the
complex changing one coordinate per step.

\subsection{Numerically stable dequantization}
Use the shifted form
\[
F_\varepsilon(x)=A-\varepsilon\log\sum_{i\in S}\exp\!\Bigl(-\frac{m_i(x)-A}{\varepsilon}\Bigr),
\qquad A=\min_{i\in S}m_i(x),
\]
in which all exponents are $\le0$ and the minimizing term equals $1$. Exact in
real arithmetic, stable in floating point, cost $O(|S|)$.

\section{Applications}

\textbf{Social choice.} For cardinal aggregation with real-valued reports the
theorems say: the only rules respecting worst-case merging and scale shifts are
weighted minima; decisive coalitions form a principal filter; dictatorship is a
singleton support; the failure of anonymity is exactly $1-1/\binom{n}{k}$; and
any single voter can seize decisiveness unilaterally.

\textbf{Scheduling and min-plus control.} Min-plus linear systems model
discrete-event dynamics. Theorem~\ref{thm:repr} says a scalar min-plus-linear,
normalized read-out is exactly a row of a tropical matrix; the support is the set
of resources on the critical path and $\delta_i$ is the slack of resource $i$.
The chamber complex decomposes state space by which resource is critical, and the
exchange law says criticality is transferred by a single-resource adjustment.

\textbf{Piecewise-linear learning.} A $\min$-pooling unit over affine features is
a tropical linear form; $\ReLU$ networks are tropical rational functions. The
chamber decomposition is the linear-region decomposition of the unit;
Theorem~\ref{thm:codim} gives the codimension of region boundaries;
Theorem~\ref{thm:facelattice} identifies the face lattice; and
Corollary~\ref{cor:unif} is the standard softmin smoothing bound
$0\le\min_i a_i-\mathrm{softmin}_\varepsilon(a)\le\varepsilon\log|S|$.
Theorem~\ref{thm:exact} says the surrogate is exact only in the degenerate
one-feature case.

\textbf{Statistical physics.} With $\varepsilon$ the temperature and $m_i(x)$ the
energy levels, $F_\varepsilon$ is the Helmholtz free energy and $F$ the
ground-state energy; the sandwich bounds their gap by temperature times maximal
entropy.

\section{Discussion and future directions}

\subsection{A dictionary}

\begin{center}
\begin{tabular}{lll}
\toprule
tropical & social choice & geometry/physics\\
\midrule
support $S$ & minimal decisive coalition & active monomials\\
$|S|=1$ & dictatorship & nondegenerate ground state\\
weight $\delta_i$ & threshold before $i$ is heard & offset of the $i$-th piece\\
$\delta\equiv0$ & selectivity & monomials through the origin\\
$S=\voters,\ \delta\equiv0$ & anonymity / unanimity & symmetric fan\\
dependence family & principal filter on $S$ & ---\\
ultrafilter & dictatorship & zero entropy\\
$|D(x)|=t$ & $t$ voters decisive at once & cell of codimension $t-1$\\
single-voter exchange & unilateral seizure & adjacency across a wall\\
$\varepsilon\log|S|$ & entropy of the coalition & free-energy gap\\
\bottomrule
\end{tabular}
\end{center}

\subsection{Limitations}
Tropical additivity is strong: it forces monotonicity and excludes the mean and
(generically) the median. The framework characterizes \emph{bottleneck}
aggregation rather than average-case aggregation. A dual max-plus theory follows
by $x\mapsto-x$; a self-dual min-max theory would be richer and is not treated
here. Finally the electorate is finite throughout; on infinite electorates
ultrafilters need not be principal and one should expect dependence filters with
no dictator, matching the classical infinite-population phenomenon.

\subsection{Open directions}
\begin{enumerate}
\item \textbf{Tropical rational aggregators.} Characterize maps satisfying (T2),
(T3) and preserving both $\min$ and $\max$ suitably; these should be tropical
rational functions, with a coalition-versus-coalition social reading.
\item \textbf{Higher-codimension exchange.} Extend Theorem~\ref{thm:exch} to a
strong-exchange statement describing paths between arbitrary cells with a
prescribed number of coordinate changes.
\item \textbf{Defect for randomized rules.} For a distribution over supports the
expected defect is $1-\mathbb{E}[1/\binom{n}{K}]$; characterize the minimizers
subject to a decisiveness constraint.
\item \textbf{Rate-optimality of dequantization.} Is $\varepsilon\log|S|$ the
exact modulus of the deformation in $L^p$ over bounded regions of tropical
projective space, and what metric does it induce on aggregators?
\item \textbf{Infinite electorates.} Extend the dependence-filter analysis to
infinite $\voters$ with a continuity axiom, and determine which non-principal
filters arise.
\end{enumerate}

\subsection{Summary}
Replacing Boolean aggregation by min-plus aggregation replaces Arrow's
impossibility by a classification. Every rule obeying the three tropical axioms
is a weighted minimum with unique support and weights; its decisive coalitions
form the principal filter of that support; the ultrafilter dichotomy holds
exactly when the support is a single voter; anonymity forces unanimity, with an
exact defect $1-1/\binom{n}{k}$ in between; the geometry of decisiveness is a
polyhedral complex whose face lattice is the reversed lattice of subcoalitions,
whose cells have codimension one less than their label size, and whose
adjacencies are single-voter exchanges; and dictatorship is precisely the unique
aggregator surviving the passage from classical to tropical arithmetic without
deformation.

